              'request for the second page with base USD',
            ),
          ),
        ),
      ).called(1);
    });

    testWidgets('should keep search working after the next page is appended', (WidgetTester tester) async {
      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          ],
          child: const CurrencyListPage(),
